public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int Q = sc.nextInt();
    boolean[] teeth = new boolean[N];

    // Initialize all teeth as present
    for (int i = 0; i < N; i++) {
        teeth[i] = true;
    }

    // Process each treatment
    for (int i = 0; i < Q; i++) {
        int T_i = sc.nextInt();
        // Toggle the tooth presence
        teeth[T_i - 1] = !teeth[T_i - 1];
    }

    // Count remaining teeth
    int remainingTeeth = 0;
    for (int i = 0; i < N; i++) {
        if (teeth[i]) {
            remainingTeeth++;
        }
    }

    System.out.println(remainingTeeth);
}
